files./app.css:
html{background:#f6f6f8}
body{margin:0;font-family:-apple-system,system-ui,sans-serif;color:#1d1d1f;background:#f6f6f8}
header{display:flex;align-items:center;gap:10px;padding:16px 20px;font-weight:700;font-size:18px;background:#fff;border-bottom:1px solid #ececf0}
.logo{width:24px;height:24px;border-radius:7px;background:linear-gradient(135deg,#ff7a45,#e5484d)}
main{padding:24px 18px 40px;max-width:980px;margin:0 auto}
h1{font-size:30px;margin:6px 0 6px;text-align:center}.sub{text-align:center;color:#6e6e73;margin:0 0 20px}
.switch{display:flex;width:max-content;margin:0 auto 24px;background:#e9e9ee;border-radius:12px;padding:4px}
.switch button{border:0;background:none;padding:9px 16px;border-radius:9px;font:600 15px -apple-system,system-ui;color:#3a3a3c}
.switch button.on{background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.12)}
.save{color:#1f9d55;font-weight:600;font-size:13px;margin-left:4px}
.plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
.plan{position:relative;background:#fff;border-radius:16px;padding:20px;box-shadow:0 1px 3px rgba(0,0,0,.06)}
.plan.pro{outline:2px solid #5b5bd6}
.tag{position:absolute;top:-11px;left:20px;background:#5b5bd6;color:#fff;font-size:12px;font-weight:600;padding:3px 10px;border-radius:99px}
h2{font-size:17px;margin:0 0 8px}.price b{font-size:34px}.price span{color:#6e6e73;margin-left:4px}
.bill{color:#1f9d55;font-size:13px;margin:4px 0 0}
ul{padding-left:18px;color:#3a3a3c;line-height:1.7;font-size:14px}
.btn{display:block;text-align:center;padding:11px;border-radius:10px;background:#5b5bd6;color:#fff;font-weight:600;text-decoration:none}
.btn.ghost{background:#f0f0f5;color:#1d1d1f}
